// Kota kontrolu (19 Eyl 2026). Bu akista daha once HIC limit yoktu: webhook
// kimlik dogrulamasiz oldugu icin adresini bilen herkes sinirsiz cagirabiliyordu.
// Kota kullanici bazli: backend gercek kimligi govdede 'kkbKimlik' olarak
// yolluyor. WordPress'ten gelen giris yapmamis isteklerde bu alan olmaz, o
// zaman IP'ye duseriz. IP tek basina guvenilir degil (mobil veride degisir,
// ortak wifi'de birlesir), bu yuzden kimlik varsa o tercih edilir.
//
// ONEMLI: cikti girdinin AYNISI olmali, uzerine yalnizca bayrak eklenir.
// Alan beyaz listesi yapilirsa asagidaki dugumler body'yi bulamaz -- ayni
// hata 11 Eyl 2026'da 'Plan Yaniti'nda replik alanini dusurmustu.
const girdi = $input.first().json;
const kimlikGovde = girdi.body || girdi;
const ip = kimlikGovde.kkbKimlik || girdi.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || girdi.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const key = 'rl_videoolus_' + ip + '_' + today;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
// 7 gunden eski sayaclari sil, yoksa static data sinirsiz buyur.
const silSiniri = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.rateLimits)) {
  const kTarih = k.slice(-10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(kTarih) && kTarih < silSiniri) delete staticData.rateLimits[k];
}
const current = staticData.rateLimits[key] || 0;
if (current >= 50) {
  return [{ json: { ...girdi, rateLimitExceeded: true } }];
}
staticData.rateLimits[key] = current + 1;
return [{ json: { ...girdi, rateLimitExceeded: false } }];

/**
 * KOTA YANITI -- gunluk sinir dolunca doner.
 *
 * Bu akis responseMode='lastNode' kullaniyor; HTTP 429 dondurmek icin butun
 * basari yollarina ayrica 'Respond to Webhook' dugumu eklemek gerekirdi.
 * Onun yerine akisin kendi hata kalibina uyuyoruz -- frontend zaten `error`
 * alanini kullaniciya gosteriyor.
 */
return [{ json: {
  // Backend bu isareti gorunce 429 dondurur; aylik hak ve kredi HARCANMAZ.
  _kotaDoldu: true,
  _parseError: true,
  error: 'Günlük kullanım sınırına ulaştınız. Yarın tekrar deneyebilirsiniz.',
} }];

/**
 * RESPONSE TRANSFORM — Gemini cevabını çözümler
 * n8n düğümü: "Response Transform" (Code)
 * ─────────────────────────────────────────────────────────────────────────────
 * MiniMax sürümünden üç fark:
 *   - Cevap yolu farklı: candidates[0].content.parts[].text
 *   - <think> temizliği GEREKMİYOR — Gemini reasoning bloğu döndürmüyor
 *   - TR_RESTORE (GBK karakter onarımı) KALDIRILDI — o MiniMax'a özgü bir
 *     kodlama hatasıydı, Gemini'de karşılığı yok
 *
 * responseMimeType: 'application/json' istendiği için cevap genelde temiz JSON
 * geliyor; yine de markdown sarmalayıcı ve sondaki fazla virgül gibi sapmalara
 * karşı onarım katmanı korundu.
 */

const cevap = $input.first().json;

// Gemini engelleme/durdurma bildirirse sessiz boş cevap yerine açık hata ver.
const aday = cevap?.candidates?.[0];
if (!aday) {
  const sebep = cevap?.promptFeedback?.blockReason
    || cevap?.error?.message
    || 'bilinmiyor';
  return [{ json: { _parseError: true, error: 'Gemini yanıt vermedi: ' + sebep } }];
}
if (aday.finishReason && !['STOP', 'MAX_TOKENS'].includes(aday.finishReason)) {
  return [{ json: { _parseError: true, error: 'Gemini isteği durdurdu: ' + aday.finishReason } }];
}

/*
 * thought:true parçaları AYIKLANIYOR. Gemini 3.x düşünen bir model;
 * varsayılanda akıl yürütme parçalarını döndürmüyor ama thinkingConfig
 * değişirse dönebilir. Filtre olmadan düşünce metni JSON'un başına
 * karışıp çözümlemeyi bozardı.
 */
let text = (aday.content?.parts || [])
  .filter((p) => !p?.thought)
  .map((p) => p?.text || '')
  .join('')
  .trim();

// ```json ... ``` sarmalayıcısını kaldır
text = text.replace(/```(?:json)?/gi, '');

const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);

/** Sondaki fazla virgül ve kontrol karakterleri modelin en sık iki sapması. */
function tryParseJson(raw) {
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch (e1) {
    const onarilmis = raw
      .replace(/,\s*([\]}])/g, '$1')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    try {
      return { ok: true, value: JSON.parse(onarilmis) };
    } catch (e2) {
      return { ok: false, error: e1.message };
    }
  }
}

const parsed = tryParseJson(text);
if (!parsed.ok) {
  return [{ json: {
    _parseError: true,
    _rawText: text.slice(0, 500),
    error: 'AI çıktısı geçerli JSON değildi: ' + parsed.error,
  } }];
}

return [{ json: { ...parsed.value, _ok: true } }];

/**
 * VIDEO KAYNAĞI — link türünü belirler
 * n8n düğümü: "Video Kaynağı" (Code)
 * ─────────────────────────────────────────────────────────────────────────────
 * Gemini video girişini iki yolla kabul ediyor:
 *   - fileData   → YouTube linkini DOĞRUDAN okur, indirme gerekmez
 *   - inlineData → base64 video baytı; diğer tüm kaynaklar için
 *
 * TikTok/Instagram linkini Gemini açamıyor, o yüzden önce indirilmesi gerekiyor.
 * Bu düğüm hangi yolun kullanılacağına karar veriyor.
 */

const body = $('Webhook').first().json.body || $('Webhook').first().json;
const videoUrl = String(body.videoUrl || body.video_url || '').trim();

/*
 * İKİ MOD (13 Eyl 2026):
 *   video     → örnek bir videodan format çıkarılır (eski davranış)
 *   kampanya  → video yok; senaryolar firmanın kampanya/hizmet metninden ve
 *               saklı bir kurgudan yazılır
 * Mod gövdede gelmiyorsa link varlığına bakılır — eski istekler bozulmasın.
 */
const mod = String(body.mod || '').trim() === 'kampanya' ? 'kampanya' : 'video';

if (mod === 'video' && !videoUrl) {
  return [{ json: { hata: 'Video linki boş.' } }];
}

/*
 * SİTE OKUNAMADI + HİZMET BİLGİSİ YOK → SENARYO ÜRETİLMEZ (11 Eyl 2026).
 *
 * Allianz gibi büyük siteler sunucumuzdan gelen isteğe bot korumasıyla cevap
 * veriyor (Cloudflare "Just a moment..." sayfası, HTTP 403). Model o zaman
 * firmanın hiçbir hizmetini bilmeden senaryo yazıyordu ("Dayanak: ürün iddiası
 * yok") ve kullanıcı sitenin okunamadığını hiç görmüyordu. Özden'in kararı:
 * bu durumda senaryo üretilmez; kullanıcıya iki hizmet alanından birini
 * doldurması söylenir.
 *
 * Kontrol BURADA — Apify (Instagram/TikTok indirme, ücretli) çalışmadan önce.
 */
const siteAdresi = String(body.bizUrl || '').trim();
let siteMetni = '';
try {
  const scrape = $('Firma Scrape').first().json || {};
  siteMetni = String(scrape.data || scrape.body || '')
    .replace(/<(script|style|noscript|svg|iframe)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
} catch (e) { siteMetni = ''; }

const ENGEL = /just a moment|access denied|forbidden|captcha|attention required|are you a robot|unusual traffic|request blocked|erişim engellendi/i;
const siteOkunamadi = Boolean(siteAdresi)
  && (siteMetni.length < 300 || ENGEL.test(siteMetni.slice(0, 600)));
const hizmetBilgisiVar = Boolean(String(body.hizmetler || '').trim() || String(body.note || '').trim());

/*
 * Kampanya modunda video yok; senaryolar YALNIZCA hizmet/kampanya metninden
 * çıkıyor. O metin de yoksa üretilecek bir şey kalmıyor — açıkça söylüyoruz.
 */
if (mod === 'kampanya' && !hizmetBilgisiVar && (siteOkunamadi || !siteMetni)) {
  return [{ json: { hata:
    'Kampanya modunda senaryo yazabilmek için ürün/kampanya bilgisi gerekiyor. '
    + '"Bu video hangi hizmet veya ürününüz için?" ya da "Sunduğunuz hizmet / ürün" '
    + 'alanını doldurun.' } }];
}

if (siteOkunamadi && !hizmetBilgisiVar) {
  const alanAdi = siteAdresi.replace(/^https?:\/\/(www\.)?/i, '').split('/')[0];
  return [{ json: { hata:
    `Web sitenizden (${alanAdi}) hizmet bilgisi okunamadı — site otomatik erişime kapalı `
    + 'ya da içeriği boş görünüyor. Bu yüzden senaryo üretilmedi. '
    + '"Bu video hangi hizmet veya ürününüz için?" ya da "Sunduğunuz hizmet / ürün" '
    + 'alanlarından birini doldurup yeniden deneyin.' } }];
}

/*
 * Üç kaynak, üç yol:
 *   youtube   → Gemini linki doğrudan okur, indirme yok, maliyet sıfır
 *   instagram → apify/instagram-scraper (directUrls) ≈ $0.0027/reel
 *   tiktok    → clockworks/tiktok-video-scraper       ≈ $0.005/video
 * Son ikisi indirilip base64 olarak Gemini'ye gidiyor.
 */
const youtubeMu   = /(?:youtube\.com\/(?:watch|shorts|embed)|youtu\.be\/)/i.test(videoUrl);
const instagramMi = /instagram\.com\/(?:reel|reels|p|tv)\//i.test(videoUrl);

const platform = mod === 'kampanya' ? '' : (youtubeMu ? 'youtube' : instagramMi ? 'instagram' : 'tiktok');

// siteOkunamadi prompt düğümlerine gidiyor: engelleme sayfasının metni firma bilgisi sanılmasın
return [{ json: { ...body, mod, videoUrl, platform, siteOkunamadi } }];

/**
 * VİDEO HATASI — indirme/hazırlık başarısızsa kullanıcıya anlamlı mesaj
 * n8n düğümü: "Video Hatası" (Code)
 *
 * NEDEN: 'Gemini Gövde' düğümleri indirme başarısız olduğunda apiBodyStr:null
 * ve açıklayıcı bir `hata` alanı döndürüyor. Eskiden bu doğrudan Gemini API'ye
 * gidiyor, boş gövde reddediliyor ve workflow 500 veriyordu — kullanıcı
 * "Araç şu an kullanılamıyor" görüyor, gerçek sebebi öğrenemiyordu
 * (6 Eyl 2026, TikTok denemesi).
 */
const ctx = $input.first().json;
return [{ json: {
  _parseError: true,
  error: ctx.hata || 'Video okunamadı. Linkin herkese açık olduğundan emin olun.',
} }];
